%[text] # Aufgabe 1.3: Anzeigen und unterschiedliche Darstellungen von Bildern
rgb  = imread('Auge.jpg');   % RGB-Farbbild einlesen (uint8)
grau = rgb2gray(rgb);           % in Grauwertbild umwandeln (uint8, 0...255)
%%
%[text] ## a) Grauwertbild mit drei verschiedenen Colormaps
figure

subplot(1,3,1)
imshow(grau)
colormap(gca, gray(256))
colorbar
title('gray')

subplot(1,3,2)
imshow(grau)
colormap(gca, hsv(256))
colorbar
title('hsv')

subplot(1,3,3)
imshow(grau)
colormap(gca, jet(256))
colorbar
title('jet')
%%
%[text] ## b) Bild als 2D-Funktion mit `surf`
z     = double(grau);        % Höhe = Grauwert (0...255)
farbe = double(rgb) / 255;   % RGB-Farben für surf im Bereich 0...1
%[text] Oberfläche zeichnen und mit `hold on` zusätzlich das Bild als Ebene bei z = 0 darunter legen:
figure %[output:1ec48f1b]
surf(z, farbe, 'EdgeColor', 'none')                  % Oberfläche (Höhe = Grauwert) %[output:1ec48f1b]
hold on %[output:1ec48f1b]
surf(zeros(size(z)), farbe, 'EdgeColor', 'none')     % Projektion bei z = 0 %[output:1ec48f1b]
hold off %[output:1ec48f1b]

axis ij          %[output:1ec48f1b]
axis tight %[output:1ec48f1b]
zlim([0 300]) %[output:1ec48f1b]
pbaspect([1 1 1.2]) %[output:1ec48f1b]
view(-35, 35) %[output:1ec48f1b]
xlabel('x'), ylabel('y'), zlabel('Grauwert') %[output:1ec48f1b]
title('Bild als 2D-Funktion') %[output:1ec48f1b]

